import * as React from 'react';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Container from '@mui/material/Container';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { styled } from '@mui/material/styles';

// Styled video component with proper positioning and overlay
const StyledVideo = styled('video')({
  position: 'absolute',
  width: '100%',
  height: '100%',
  top: 0,
  left: 0,
  objectFit: 'cover',
  opacity: 0.5,
  zIndex: -1,
});

export default function Hero() {
  return (
    <Box
      id="hero"
      sx={(theme) => ({
        width: '100%',
        backgroundRepeat: 'no-repeat',
        backgroundImage:
          'radial-gradient(ellipse 80% 50% at 50% -20%, hsl(210, 100%, 90%), transparent)',
        ...theme.applyStyles('dark', {
          backgroundImage:
            'radial-gradient(ellipse 80% 50% at 50% -20%, hsl(210, 100%, 16%), transparent)',
        }),
      })}
    >
      <Container
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          pt: { xs: 14, sm: 20 },
          pb: { xs: 8, sm: 12 },
          px: { xs: 2, sm: 4 },
        }}
      >
        <Stack
          spacing={2}
          useFlexGap
          sx={{ 
            alignItems: 'center', 
            width: { xs: '100%', sm: '80%', md: '70%' },
            maxWidth: '1200px' 
          }}
        >
          <Typography
            component="h1"
            variant="h1"
            sx={{
              fontSize: { xs: '2.5rem', sm: '3rem', md: '3.5rem' },
              textAlign: 'center',
              width: '100%',
              lineHeight: { xs: 1.2, sm: 1.4 },
              mb: { xs: 2, sm: 3 },
            }}
          >
            <Box 
              sx={{ 
                display: 'flex',
                flexDirection: { xs: 'column', sm: 'row' },
                alignItems: 'center',
                justifyContent: 'center',
                gap: { xs: 1, sm: 2 }
              }}
            >
              <span>We build</span>
              <Typography
                component="span"
                variant="inherit"
                sx={(theme) => ({
                  color: 'primary.main',
                  ...theme.applyStyles('dark', {
                    color: 'primary.light',
                  }),
                })}
              >
                products
              </Typography>
              <span>that shape a better future</span>
            </Box>
          </Typography>

          <Typography
            sx={{
              textAlign: 'center',
              color: 'text.secondary',
              width: { xs: '100%', sm: '90%', md: '80%' },
              px: { xs: 2, sm: 4 },
              fontSize: { xs: '1rem', sm: '1.1rem' },
              lineHeight: 1.6,
            }}
          >
            We're the architects of digital excellence across industries. We redefine business with cutting-edge digital strategies that invokes sector-wide transformation.
          </Typography>

          <Button
            variant="contained"
            color="primary"
            size="large"
            sx={{ 
              minWidth: 'fit-content',
              px: 4,
              py: 1.5,
              mt: { xs: 2, sm: 3 }
            }}
          >
            Book a Call
          </Button>
        </Stack>
        <StyledVideo
          autoPlay
          muted
          loop
          playsInline
          id="video"
        >
          <source 
            src="https://cdn.prod.website-files.com/66578fd98f1535d11770d8a7%2F67478059a3dc6f2ef9f2d7c7_Speck%20Design%20Home%20Background%20Video%20v3_2-transcode.mp4" 
            type="video/mp4"
          />
          Your browser does not support the video tag.
        </StyledVideo>
      </Container>
    </Box>
  );
}
